-- Reproducible my-agent baseline for local reset/CI.
create extension if not exists pgcrypto;
create table if not exists public.agent_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.agent_access_keys(id uuid primary key default gen_random_uuid(),key_prefix text not null unique,key_hash text not null unique,user_id uuid references auth.users(id) on delete set null,plan text not null default 'pro',status text not null default 'active' check(status in('active','paused','revoked')),expires_at timestamptz,daily_limit integer not null default 500,monthly_limit integer not null default 10000,created_at timestamptz not null default now(),last_used_at timestamptz);
create table if not exists public.agent_usage_daily(key_id uuid not null references public.agent_access_keys(id) on delete cascade,usage_date date not null default current_date,requests integer not null default 0,input_tokens bigint not null default 0,output_tokens bigint not null default 0,primary key(key_id,usage_date));
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.agent_plans(id text primary key,title text not null,description text,price_cents integer not null default 0,currency text not null default 'USD',days integer not null default 30,daily_limit integer not null default 500,monthly_limit integer not null default 10000,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.agent_payment_orders(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,plan_id text references public.agent_plans(id) on delete set null,provider text not null default 'stripe',provider_checkout_id text unique,provider_customer_id text,amount_cents integer not null default 0,currency text not null default 'USD',status text not null default 'pending',access_key_id uuid references public.agent_access_keys(id) on delete set null,created_at timestamptz not null default now(),paid_at timestamptz,metadata jsonb not null default '{}'::jsonb);
create table if not exists public.agent_payment_events(id uuid primary key default gen_random_uuid(),provider text not null,event_id text not null unique,event_type text not null,order_id uuid references public.agent_payment_orders(id) on delete set null,payload jsonb not null default '{}'::jsonb,processed_at timestamptz not null default now());
create table if not exists public.agent_conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.agent_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.agent_conversations(id) on delete cascade,role text not null check(role in('system','user','assistant','tool')),content jsonb not null default '{}'::jsonb,tool_calls jsonb,created_at timestamptz not null default now());
create table if not exists public.agent_memories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,content text not null,kind text not null default 'fact',importance smallint not null default 50,source_conversation_id uuid references public.agent_conversations(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.agent_ai_requests(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,access_key_id uuid references public.agent_access_keys(id) on delete set null,conversation_id uuid references public.agent_conversations(id) on delete set null,provider text not null,model text not null,input_tokens bigint not null default 0,output_tokens bigint not null default 0,total_tokens bigint not null default 0,latency_ms integer,status text not null default 'success',error_code text,created_at timestamptz not null default now());
create table if not exists public.agent_tools(id uuid primary key default gen_random_uuid(),name text not null unique,description text not null,input_schema jsonb not null default '{}'::jsonb,server_only boolean not null default true,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.agent_plans(id,title,description,price_cents,currency,days,daily_limit,monthly_limit,active) values('pro','Agent Pro','Полный доступ к AI-агенту',990,'USD',30,500,10000,true),('pro_year','Agent Pro — год','Годовой доступ к AI-агенту',7900,'USD',365,1000,30000,true) on conflict(id) do nothing;
alter table public.agent_profiles enable row level security;alter table public.agent_access_keys enable row level security;alter table public.agent_usage_daily enable row level security;alter table public.admin_users enable row level security;alter table public.agent_plans enable row level security;alter table public.agent_payment_orders enable row level security;alter table public.agent_payment_events enable row level security;alter table public.agent_conversations enable row level security;alter table public.agent_messages enable row level security;alter table public.agent_memories enable row level security;alter table public.agent_ai_requests enable row level security;alter table public.agent_tools enable row level security;
create index if not exists agent_access_keys_status_idx on public.agent_access_keys(status);create index if not exists agent_access_keys_user_id_idx on public.agent_access_keys(user_id);create index if not exists agent_usage_daily_date_idx on public.agent_usage_daily(usage_date);create index if not exists agent_payment_orders_user_idx on public.agent_payment_orders(user_id);create index if not exists agent_payment_orders_status_idx on public.agent_payment_orders(status);create index if not exists agent_payment_orders_access_key_idx on public.agent_payment_orders(access_key_id);create index if not exists agent_payment_orders_plan_idx on public.agent_payment_orders(plan_id);create index if not exists agent_payment_events_order_idx on public.agent_payment_events(order_id);create index if not exists agent_conversations_user_id_idx on public.agent_conversations(user_id,updated_at desc);create index if not exists agent_messages_conversation_idx on public.agent_messages(conversation_id,created_at);create index if not exists agent_memories_user_idx on public.agent_memories(user_id,importance desc,updated_at desc);create index if not exists agent_memories_source_conversation_idx on public.agent_memories(source_conversation_id);create index if not exists agent_ai_requests_user_time_idx on public.agent_ai_requests(user_id,created_at desc);create index if not exists agent_ai_requests_conversation_idx on public.agent_ai_requests(conversation_id,created_at desc);create index if not exists agent_ai_requests_model_time_idx on public.agent_ai_requests(provider,model,created_at desc);create index if not exists agent_ai_requests_access_key_idx on public.agent_ai_requests(access_key_id,created_at desc);
create or replace function public.consume_agent_request(p_key_hash text,p_daily_limit integer,p_monthly_limit integer) returns table(key_id uuid,plan text,expires_at timestamptz,daily_used integer,daily_limit integer,monthly_used bigint,monthly_limit integer) language plpgsql security definer set search_path='' as $$ declare k public.agent_access_keys%rowtype;d integer;m bigint;begin select * into k from public.agent_access_keys where key_hash=p_key_hash and status='active' and (expires_at is null or expires_at>now()) for update;if not found then return;end if;select coalesce(sum(requests),0) into m from public.agent_usage_daily where key_id=k.id and usage_date>=date_trunc('month',current_date)::date;if m>=least(k.monthly_limit,greatest(p_monthly_limit,1)) then return;end if;insert into public.agent_usage_daily(key_id,usage_date,requests) values(k.id,current_date,1) on conflict(key_id,usage_date) do update set requests=public.agent_usage_daily.requests+1 returning requests into d;if d>least(k.daily_limit,greatest(p_daily_limit,1)) then update public.agent_usage_daily set requests=requests-1 where key_id=k.id and usage_date=current_date;return;end if;update public.agent_access_keys set last_used_at=now() where id=k.id;select coalesce(sum(requests),0) into m from public.agent_usage_daily where key_id=k.id and usage_date>=date_trunc('month',current_date)::date;return query select k.id,k.plan,k.expires_at,d,k.daily_limit,m,k.monthly_limit;end$$;
create or replace function public.agent_touch_updated_at() returns trigger language plpgsql security invoker set search_path=public as $$begin new.updated_at=now();return new;end$$;
create or replace function public.handle_new_agent_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.agent_profiles(user_id,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url') on conflict(user_id) do nothing;return new;end$$;
create or replace function public.agent_admin_stats() returns jsonb language plpgsql security definer set search_path=public as $$declare r jsonb;begin select jsonb_build_object('users',(select count(*) from auth.users),'keys_total',(select count(*) from agent_access_keys),'keys_active',(select count(*) from agent_access_keys where status='active'),'requests_today',(select coalesce(sum(requests),0) from agent_usage_daily where usage_date=current_date),'ai_requests_today',(select count(*) from agent_ai_requests where created_at>=current_date),'ai_errors_today',(select count(*) from agent_ai_requests where created_at>=current_date and status<>'success'),'paid_orders',(select count(*) from agent_payment_orders where status='paid'),'revenue_cents',(select coalesce(sum(amount_cents),0) from agent_payment_orders where status='paid')) into r;return r;end$$;
drop trigger if exists on_auth_user_created_agent_profile on auth.users;create trigger on_auth_user_created_agent_profile after insert on auth.users for each row execute function public.handle_new_agent_profile();
drop trigger if exists agent_conversations_touch_updated_at on public.agent_conversations;create trigger agent_conversations_touch_updated_at before update on public.agent_conversations for each row execute function public.agent_touch_updated_at();
drop trigger if exists agent_memories_touch_updated_at on public.agent_memories;create trigger agent_memories_touch_updated_at before update on public.agent_memories for each row execute function public.agent_touch_updated_at();
drop trigger if exists agent_tools_touch_updated_at on public.agent_tools;create trigger agent_tools_touch_updated_at before update on public.agent_tools for each row execute function public.agent_touch_updated_at();